<script setup lang="ts">import {computed} from 'vue';import type {Run} from '../types/domain';import {number} from '../utils/format';const props=defineProps<{run:Run}>();const points=computed(()=>props.run.result.points||[]);const range=computed(()=>{const vals=points.value.flatMap(p=>[p.actual,p.prediction]);const min=Math.min(...vals),max=Math.max(...vals),pad=Math.max(10,(max-min)*.08);return [min-pad,max+pad];});const sx=(v:number)=>65+(v-range.value[0])/(range.value[1]-range.value[0])*460;const sy=(v:number)=>270-(v-range.value[0])/(range.value[1]-range.value[0])*220;const colors=['#9b513c','#6c7464','#ac905d'];</script><template><section class="prediction-plot"><div class="plot-heading"><h2>未见楼宇 · 真实值与预测值</h2><span>{{points.length}}个封存楼宇日</span></div><svg v-if="points.length" viewBox="0 0 590 320" role="img" aria-label="封存楼宇日能耗的真实与预测散点"><g v-for="t in [0,.25,.5,.75,1]" :key="t" class="prediction-grid"><line x1="65" x2="525" :y1="50+t*220" :y2="50+t*220"/><line :x1="65+t*460" :x2="65+t*460" y1="50" y2="270"/><text x="54" :y="54+t*220" text-anchor="end">{{number(range[1]-t*(range[1]-range[0]),0)}}</text><text :x="65+t*460" y="289" text-anchor="middle">{{number(range[0]+t*(range[1]-range[0]),0)}}</text></g><line x1="65" x2="525" y1="270" y2="50" class="parity-line"/><circle v-for="p in points" :key="p.id" :cx="sx(p.actual)" :cy="sy(p.prediction)" r="2.5" :fill="colors[(run.result.split?.test_buildings.indexOf(p.building_code)||0)%3]" opacity=".65"><title>{{p.building_code}} / {{p.day}} / 真值{{p.actual}} / 预测{{p.prediction}}</title></circle><text x="65" y="23" class="axis-label">预测能耗 / kWh</text><text x="525" y="314" text-anchor="end" class="axis-label">实际能耗 / kWh</text></svg><div class="building-legend"><span v-for="(b,i) in run.result.split?.test_buildings" :key="b" :style="{color:colors[i%3]}">● {{b}}</span><small>虚线为预测=真实</small></div></section></template>
